import React from 'react';
import { useNavigate } from 'react-router-dom';
import FranchiseList from './FranchiseList';
import { logout } from '../services/api';
import { Button, Container, Box, Typography, Grid, Paper } from '@mui/material';

const Dashboard = () => {
  const navigate = useNavigate();

  const handleLogout = async () => {
    try {
      await logout(navigate);
      localStorage.removeItem('token');
      navigate('/login');
    } catch (error) {
      console.error('Logout failed:', error);
      alert('There was an error logging out. Please try again.');
    }
  };

  return (
    <Container maxWidth="lg" sx={{ mt: 4 }}>
      <Paper elevation={4} sx={{ p: 4, mb: 4 }}>
        <Typography
          variant="h4"
          align="center"
          gutterBottom
          sx={{ mb: 6 }} // Increased margin below the header
        >
          Welcome To Superadmin Dashboard
        </Typography>
        <Grid container spacing={4} sx={{ mb: 4 }}>
          <Grid item xs={12} md={3}>
            <Button
              variant="contained"
              color="primary"
              fullWidth
              onClick={() => navigate('/create-superadmin')}
            >
              Create User
            </Button>
          </Grid>
          <Grid item xs={12} md={3}>
            <Button
              variant="contained"
              color="secondary"
              fullWidth
              onClick={() => navigate('/create-franchise')}
            >
              Create Franchise
            </Button>
          </Grid>
          <Grid item xs={12} md={3}>
            <Button
              variant="contained"
              color="info"
              fullWidth
              onClick={() => navigate('/exam-data')}
            >
              Manage Exam Data
            </Button>
          </Grid>
          <Grid item xs={12} md={3}>
            <Button
              variant="contained"
              color="error"
              fullWidth
              onClick={handleLogout}
            >
              Logout
            </Button>
          </Grid>
        </Grid>
      </Paper>

      <Paper elevation={3} sx={{ p: 3 }}>
        <Typography variant="h5" align="center" gutterBottom>
          Franchise List
        </Typography>
        <FranchiseList />
      </Paper>
    </Container>
  );
};

export default Dashboard;
